<template><view class="page home">
 <view class="home-top"><view class="between"><view class="brand"><text class="brand-icon">禾</text><text>青禾校园</text></view><text class="weather">☀ 今天也要好好吃饭</text></view><view class="between location-row"><view @click="chooseZone"><text class="location-dot">⌖</text><text class="location">{{location.label}}{{zone!=='全部'?' · '+zone:location.label==='手动选择'?' · 全部区域':''}}</text><text class="chevron">⌄</text></view><text class="small muted">美味，就在身边</text></view>
 <view class="search"><text class="search-icon">⌕</text><input v-model="search" placeholder="今天想吃点什么？" confirm-type="search" @confirm="load"/><text class="search-button" @click="load">搜索</text></view>
 <view class="hero" @click="go('store/index?id=2')"><view class="hero-copy"><view class="hero-label">FRESH EVERY DAY</view><view class="hero-title">吃点新鲜的<view>给生活加点绿</view></view><view class="hero-sub">一份轻食，一整天的好状态</view><view class="hero-cta">发现今日好味 <text>↗</text></view></view><image class="hero-image" src="/static/food/salad.jpg" mode="aspectFill"/><view class="hero-sticker">新鲜<view>刚刚好</view></view></view>
 <view class="category-grid"><view v-for="c in categories" :key="c.name" class="category" @click="selectCategory(c)"><view :class="['category-icon',{chosen:category===c.name||zone===c.name}]" :style="{background:c.color}">{{c.icon}}</view><text>{{c.name}}</text></view></view></view>
 <view class="content home-content"><view v-if="pending" class="card" @click="go('checkout/index')"><view class="bold">有一笔下单结果待确认 ›</view><view class="subtitle">点击查询原订单，避免重复下单</view></view><view class="member-banner" @click="go('benefits/index')"><view class="row"><text class="member-medal">♛</text><view><view class="member-title">把每一餐，吃出小确幸</view><view class="member-sub">新朋友专享 ¥3 优惠券 · 好味不贵</view></view></view><text class="member-arrow">›</text></view>
 <view class="section-head between"><view><view class="section-kicker">GOOD FOOD, GOOD MOOD</view><view class="title" style="margin-top:8rpx">附近的好味道<text class="green-dot">.</text></view></view><text class="small muted">{{total}} 家好店</text></view>
 <view class="sort-row"><view v-for="s in sorts" :key="s.key" :class="['sort',{active:sort===s.key}]" @click="selectSort(s.key)">{{s.name}}</view><text class="sort" @click="onlyFree=!onlyFree">{{onlyFree?'低配送费 ✓':'筛选 ☷'}}</text></view>
 <scroll-view scroll-x class="filter-scroll"><view class="chips"><view :class="['filter-chip',{selected:category==='全部'}]" @click="reset">全部好店</view><view class="filter-chip" @click="category='家常菜'">热乎家常饭</view><view class="filter-chip" @click="category='轻食沙拉'">清爽低负担</view><view class="filter-chip" @click="category='甜品饮品'">下午茶时光</view></view></scroll-view>
 <view v-if="error" class="error" @click="load">{{error}} · 点击重试</view><view v-if="loading&&!filtered.length" class="empty">正在寻找校园好味道…</view>
 <view v-for="store in filtered" :key="store.id" class="store-card" @click="go('store/index?id='+store.id)"><image :src="store.image" mode="aspectFill" class="store-image"/><view class="store-info"><view class="between"><text class="store-name">{{store.name}}</text><text class="small muted">›</text></view><view class="store-rating"><text class="star">★ {{store.rating}}</text><text class="tiny muted">月售 {{store.sales}}+</text><text class="tiny delivery">{{store.minutes}}分钟</text></view><view class="store-meta"><text>起送 ¥{{money(store.minimum)}} · 配送 ¥{{money(store.delivery_fee)}}</text><text>{{distanceText(location.point,store)}}</text></view><view class="store-tags"><text class="tag">{{store.open_now?'营业中':'未到营业时间'}}</text><text class="tag">{{store.zone}}</text><text class="tag">{{store.category}}</text></view><view class="store-promo"><text>减</text> 新朋友下单满12减3</view></view></view>
 <view v-if="!loading&&!error&&!filtered.length" class="empty">暂时没有符合条件的商家<view class="link" @click="reset">清除筛选</view></view><view v-if="filtered.length<total" class="link" style="text-align:center;padding:24rpx" @click="more">{{loading?'加载中…':'加载更多商家'}}</view><view class="end-note">— 好好吃饭，认真生活 —</view></view><BottomNav active="home"/>
</view></template>
<script setup>
import {intents} from '../../lib/recovery';const pending=ref(false);
import {ref,computed,toRef,toRefs,reactive,watch} from 'vue';import {onShow,onHide,onReachBottom} from '@dcloudio/uni-app';import BottomNav from '../../components/BottomNav.vue';import {request,go,money} from '../../lib/api';
import {location,locationActions} from '../../lib/location';import {createPagedCatalog,queryString} from '../../lib/paged-catalog.mjs';import {distanceText} from '../../lib/geo.mjs';
const zone=toRef(location,'zone');
const search=ref(''),category=ref('全部'),sort=ref('recommended'),onlyFree=ref(false);const state=reactive({rows:[],total:0,page:0,loading:false,error:''});const {rows:stores,total,loading,error}=toRefs(state);const feed=createPagedCatalog(state,p=>request('/catalog/stores?'+queryString(p),'GET',null,true));let timer,visible=false;
const categories=[{name:'一食堂',icon:'🍱',color:'#f9ecd5'},{name:'二食堂',icon:'🍜',color:'#edf0dc'},{name:'商业街',icon:'🏡',color:'#e9eee1'},{name:'炸鸡汉堡',icon:'🍔',color:'#ffedcd'},{name:'甜品饮品',icon:'🧋',color:'#f4e7da'},{name:'家常菜',icon:'🥘',color:'#f8e5d8'},{name:'轻食沙拉',icon:'🥗',color:'#e9efdc'},{name:'粉面小吃',icon:'🍝',color:'#f6ecd6'},{name:'营养早餐',icon:'🥐',color:'#f7eedb'},{name:'全部',icon:'▦',color:'#e9f0e7'}];const sorts=[{key:'recommended',name:'综合排序'},{key:'distance',name:'距离优先'},{key:'sales',name:'销量优先'}];
const filtered=computed(()=>stores.value);
function selectCategory(c){if(['一食堂','二食堂','商业街'].includes(c.name)){zone.value=c.name;category.value='全部'}else{category.value=c.name;zone.value='全部'}}function reset(){category.value='全部';zone.value='全部';search.value='';onlyFree.value=false}function chooseZone(){go('location/index')}function selectSort(key){if(key==='distance'&&!location.point)return chooseZone();sort.value=key}
function params(){return {q:search.value.trim(),zone:zone.value==='全部'?'':zone.value,category:category.value==='全部'?'':category.value,sort:sort.value,lowFee:onlyFree.value,...(location.point||{})}}
function load(){clearTimeout(timer);return feed.load(params())}function more(){return feed.load(null,true)}
watch([search,category,zone,sort,onlyFree,()=>location.point],()=>{if(!visible)return;clearTimeout(timer);timer=setTimeout(load,300)});
onShow(()=>{pending.value=!!intents.read();visible=true;locationActions.expire();if(!location.point&&sort.value==='distance')sort.value='recommended';load()});onHide(()=>{visible=false;clearTimeout(timer);feed.cancel()});onReachBottom(more);
</script>
<style scoped>
.home-top{padding:38rpx 32rpx 26rpx;background:linear-gradient(135deg,#e5eee0 0%,#f5f7ee 70%);padding-top:calc(38rpx + env(safe-area-inset-top))}.brand{display:flex;align-items:center;gap:12rpx;font-size:30rpx;letter-spacing:2rpx;font-weight:750}.brand-icon{background:#2e6047;color:#f3edce;border-radius:11rpx;padding:5rpx 9rpx;font-size:24rpx}.weather{font-size:20rpx;color:#7b8c73}.location-row{margin:30rpx 0 25rpx}.location-dot{font-size:30rpx;color:#4a7952;margin-right:8rpx}.location{font-size:26rpx;font-weight:600}.chevron{margin-left:12rpx;color:#718468}.search{background:#fff;display:flex;align-items:center;padding:10rpx 12rpx 10rpx 26rpx;border-radius:50rpx;box-shadow:0 6rpx 22rpx #38503308}.search-icon{font-size:44rpx;color:#76876c;margin-right:12rpx}.search input{flex:1;min-width:0;font-size:25rpx}.search-button{padding:17rpx 31rpx;border-radius:36rpx;background:#2e634b;color:#fff;font-size:24rpx}.hero{position:relative;overflow:hidden;height:326rpx;margin-top:28rpx;background:#e4eacb;border-radius:28rpx}.hero-copy{position:relative;padding:34rpx 28rpx;z-index:2}.hero-label{font-size:16rpx;letter-spacing:4rpx;color:#7a8760}.hero-title{font-size:42rpx;line-height:1.4;font-weight:800;margin-top:13rpx;color:#395737;letter-spacing:2rpx}.hero-sub{font-size:20rpx;color:#7e8c68;margin-top:10rpx}.hero-cta{font-size:22rpx;margin-top:26rpx;color:#46663a}.hero-cta text{padding-left:22rpx}.hero-image{position:absolute;right:-80rpx;bottom:-22rpx;width:380rpx;height:380rpx;border-radius:50%;transform:rotate(-10deg);border:12rpx solid #f6f4df}.hero-sticker{position:absolute;right:22rpx;top:20rpx;border-radius:50%;background:#f5edc5;padding:15rpx 18rpx;font-size:20rpx;transform:rotate(12deg);color:#687c40;z-index:3}.category-grid{display:grid;grid-template-columns:repeat(5,1fr);gap:27rpx 16rpx;margin-top:30rpx}.category{display:flex;flex-direction:column;align-items:center;font-size:23rpx;gap:12rpx;color:#48593f}.category-icon{width:83rpx;height:83rpx;display:flex;align-items:center;justify-content:space-around;border-radius:28rpx;font-size:48rpx;border:2rpx solid transparent}.category-icon.chosen{border-color:#88a277}.home-content{padding-top:24rpx}.member-banner{background:linear-gradient(110deg,#ece4ca,#f5efd9);border-radius:18rpx;padding:23rpx 25rpx;color:#796539;display:flex;align-items:center;justify-content:space-between}.member-medal{font-size:47rpx;margin-right:21rpx;color:#a28e56}.member-title{font-size:26rpx;font-weight:700}.member-sub{font-size:20rpx;margin-top:6rpx;color:#a08b58}.member-arrow{font-size:40rpx}.green-dot{color:#65916e;margin-left:8rpx}.sort-row{display:flex;justify-content:space-between;margin-bottom:24rpx}.sort{font-size:25rpx;color:#8b9683}.sort.active{font-weight:700;color:#345d42}.filter-scroll{margin-bottom:18rpx}.filter-chip{padding:10rpx 20rpx;border-radius:9rpx;background:#eef1e8;color:#829071;font-size:21rpx}.filter-chip.selected{background:#e5eddd;color:#5d8050}.store-card{display:flex;padding:24rpx 0;border-bottom:1rpx solid #e9ede1;gap:22rpx}.store-image{width:177rpx;height:177rpx;flex-shrink:0;border-radius:22rpx}.store-info{flex:1;min-width:0}.store-name{font-weight:700;font-size:30rpx}.store-rating{display:flex;align-items:center;gap:16rpx;margin-top:10rpx}.star{font-size:23rpx;color:#c48d35;font-weight:700}.delivery{margin-left:auto;color:#778774}.store-meta{display:flex;justify-content:space-between;font-size:20rpx;color:#94a08c;margin-top:10rpx}.store-tags{margin-top:10rpx}.store-promo{font-size:20rpx;color:#c08358;margin-top:13rpx}.store-promo text{background:#f5e9dc;padding:1rpx 5rpx;margin-right:7rpx;border-radius:4rpx}.end-note{text-align:center;color:#b4bdab;font-size:21rpx;letter-spacing:3rpx;padding:40rpx 0 5rpx}
</style>
